-- Ajuste 177: backfill de 7 itens do catalogo oficial que existem no
-- database/install.sql desde o inicio do modulo Kids, mas nunca
-- tiveram uma migracao numerada propria - qualquer igreja provisionada
-- antes desse ponto (ou cujo banco nao recebeu esses 7 por qualquer
-- outro motivo) fica pra sempre sem eles mesmo rodando todas as
-- migracoes seguintes (052...071), ja que install.sql so e usado no
-- provisionamento de igrejas NOVAS. Idempotente (INSERT ... SELECT ...
-- WHERE NOT EXISTS por titulo) - seguro rodar em qualquer igreja,
-- quantas vezes for, nunca duplica.

INSERT INTO kids_conteudos
    (tipo, origem, titulo, descricao, categoria, tema, livro_biblico, personagem, dificuldade, idade_min, idade_max, duracao_minutos, xp_recompensa, moedas_recompensa, texto_conteudo, midia_url, midia_path, capa_path, quiz_perguntas, status, created_at)
SELECT 'historia', 'kadosys', 'A Arca de Noé', 'Deus pede a Noé para construir uma arca gigante antes do grande dilúvio.', 'Velho Testamento', 'Obediência', 'Gênesis', 'Noé', 'facil', 4, 8, 8, 15, 8, 'Há muito tempo, Deus viu que as pessoas na Terra estavam fazendo coisas erradas. Mas havia um homem chamado Noé que amava a Deus. Deus pediu que Noé construísse uma arca enorme, de madeira, para salvar sua família e dois de cada animal do mundo. Noé obedeceu, mesmo sem entender tudo. Choveu por 40 dias e 40 noites, mas a arca flutuou e todos ficaram em segurança. Quando a chuva parou, Deus colocou um arco-íris no céu, prometendo nunca mais destruir a Terra com um dilúvio. Essa é a promessa do arco-íris até hoje!', NULL, NULL, NULL, NULL, 'publicado', NOW()
WHERE NOT EXISTS (SELECT 1 FROM kids_conteudos WHERE titulo = 'A Arca de Noé');

INSERT INTO kids_conteudos
    (tipo, origem, titulo, descricao, categoria, tema, livro_biblico, personagem, dificuldade, idade_min, idade_max, duracao_minutos, xp_recompensa, moedas_recompensa, texto_conteudo, midia_url, midia_path, capa_path, quiz_perguntas, status, created_at)
SELECT 'devocional', 'kadosys', 'Deus cuida de mim', 'Um devocional curto sobre o cuidado de Deus com cada criança.', 'Valores', 'Cuidado de Deus', NULL, NULL, 'facil', 3, 6, 3, 10, 5, 'Você sabia que Deus conhece até quantos fios de cabelo você tem na cabeça? Ele te ama tanto que cuida de cada detalhezinho da sua vida! Quando você acorda de manhã, Deus está com você. Quando você brinca, Deus está com você. Quando você tem medo, pode conversar com Ele, porque Ele sempre escuta. Hoje, agradeça a Deus por cuidar de você o dia inteiro!', NULL, NULL, NULL, NULL, 'publicado', NOW()
WHERE NOT EXISTS (SELECT 1 FROM kids_conteudos WHERE titulo = 'Deus cuida de mim');

INSERT INTO kids_conteudos
    (tipo, origem, titulo, descricao, categoria, tema, livro_biblico, personagem, dificuldade, idade_min, idade_max, duracao_minutos, xp_recompensa, moedas_recompensa, texto_conteudo, midia_url, midia_path, capa_path, quiz_perguntas, status, created_at)
SELECT 'estudo', 'kadosys', 'Os frutos do Espírito', 'Um estudo simples sobre as qualidades que Deus quer desenvolver em nós.', 'Novo Testamento', 'Caráter cristão', 'Gálatas', NULL, 'medio', 7, 12, 10, 15, 8, '<div class=\"texto\">A Bíblia ensina que, quando deixamos o Espírito Santo agir em nossa vida, alguns \"frutos\" aparecem: amor, alegria, paz, paciência, amabilidade, bondade, fidelidade, mansidão e domínio próprio (Gálatas 5:22-23). Assim como uma árvore boa dá frutos bons, uma vida com Deus produz essas qualidades. Qual desses frutos você quer pedir a Deus para crescer mais em você esta semana?</div>\n<div class=\"kids-corrida\" data-jogo-trivia data-rodadas=\'[{\"titulo\": \"Pergunta rápida\", \"perguntas\": [{\"pergunta\": \"Segundo Gálatas 5:22-23, os frutos do Espírito aparecem quando...\", \"alternativas\": [\"deixamos o Espírito Santo agir em nossa vida\", \"estudamos muito na escola\", \"ficamos mais velhos\", \"comemos frutas de verdade\"], \"correta\": 0}]}]\'>\n<div class=\"kids-corrida-cabecalho\">\n<span data-trivia-titulo>Pergunta rápida — 1 de 1</span>\n<span class=\"kids-corrida-estrelas\" data-trivia-estrelas>⭐ 0/1</span>\n</div>\n<div data-trivia-perguntas></div>\n</div>', NULL, NULL, NULL, NULL, 'publicado', NOW()
WHERE NOT EXISTS (SELECT 1 FROM kids_conteudos WHERE titulo = 'Os frutos do Espírito');

INSERT INTO kids_conteudos
    (tipo, origem, titulo, descricao, categoria, tema, livro_biblico, personagem, dificuldade, idade_min, idade_max, duracao_minutos, xp_recompensa, moedas_recompensa, texto_conteudo, midia_url, midia_path, capa_path, quiz_perguntas, status, created_at)
SELECT 'quiz', 'kadosys', 'Quiz: Personagens da Bíblia', 'Teste o que você sabe sobre os grandes personagens bíblicos!', 'Geral', 'Personagens', NULL, NULL, 'medio', 6, 10, 5, 20, 10, NULL, NULL, NULL, NULL, '[{\"pergunta\":\"Quem construiu a arca?\",\"alternativas\":[\"Moisés\",\"Noé\",\"Davi\",\"Abraão\"],\"correta\":1,\"explicacao\":\"Foi Noé! Deus pediu que ele construísse uma arca bem grande pra salvar sua família e os animais da grande enchente. Noé obedeceu, mesmo sem entender tudo - e Deus cumpriu a promessa de proteger quem confia nele.\"},{\"pergunta\":\"Quantos dias e noites choveu no dilúvio?\",\"alternativas\":[\"7\",\"40\",\"100\",\"3\"],\"correta\":1,\"explicacao\":\"Choveu 40 dias e 40 noites! Mesmo com tanta chuva, Noé e sua família ficaram seguros dentro da arca, porque confiaram no plano de Deus.\"},{\"pergunta\":\"Quem derrotou o gigante Golias?\",\"alternativas\":[\"Saul\",\"Salomão\",\"Davi\",\"Sansão\"],\"correta\":2,\"explicacao\":\"Foi Davi, ainda um jovem pastor! Com uma pedrinha, uma funda e muita fé em Deus, ele venceu um gigante guerreiro. Deus pode usar quem parece pequeno pra fazer coisas grandes.\"}]', 'publicado', NOW()
WHERE NOT EXISTS (SELECT 1 FROM kids_conteudos WHERE titulo = 'Quiz: Personagens da Bíblia');

