SELECT 'versiculo_ilustrado', 'kadosys', 'João 3:16', 'O versículo mais conhecido da Bíblia, em linguagem para crianças.', 'Novo Testamento', 'Amor de Deus', 'João', 'Jesus', 'facil', 4, 10, 2, 10, 5, '\"Porque Deus amou tanto o mundo, que deu o seu único Filho, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.\" João 3:16', NULL, NULL, NULL, NULL, 'publicado', NOW()
