INSERT INTO kids_conteudos
    (tipo, origem, titulo, descricao, categoria, tema, livro_biblico, personagem, dificuldade, idade_min, idade_max, duracao_minutos, xp_recompensa, moedas_recompensa, texto_conteudo, midia_url, midia_path, capa_path, quiz_perguntas, status, created_at)
SELECT 'desafio', 'kadosys', 'Desafio da Semana: Ore por alguém', 'Um desafio simples para praticar o amor ao próximo.', 'Missões', 'Oração', NULL, NULL, 'facil', 5, 12, NULL, 20, 10, 'Esta semana, escolha uma pessoa da sua família ou um amigo e ore por ela todos os dias. Pode ser um pedido de saúde, de alegria ou só agradecendo por essa pessoa existir. No fim da semana, conte pra ela que você orou!', NULL, NULL, NULL, NULL, 'publicado', NOW()
WHERE NOT EXISTS (SELECT 1 FROM kids_conteudos WHERE titulo = 'Desafio da Semana: Ore por alguém');
